package react

// reactor manages all cells created through it, in creation order.
// Creation order is a topological order of the dependency graph, since a
// compute cell can only depend on cells that already exist.
type reactor struct {
	cells []*cell
}

// cell holds a value. Input cells have a nil compute function; compute
// cells recompute their value from their dependencies.
type cell struct {
	reactor *reactor
	value   int
	compute func() int

	// dependents are the cells that directly depend on this cell.
	dependents []*cell

	// callbacks are called when the value changes to a new stable state.
	callbacks []callback

	nextCallbackID int
}

type callback struct {
	id int
	fn func(int)
}

// canceler removes a single callback from a cell.
type canceler struct {
	cell *cell
	id   int
}

// New creates a new Reactor.
func New() Reactor {
	return &reactor{}
}

// CreateInput creates an input cell with the given initial value.
func (r *reactor) CreateInput(initial int) InputCell {
	c := &cell{reactor: r, value: initial}
	r.cells = append(r.cells, c)
	return c
}

// CreateCompute1 creates a compute cell depending on one cell.
func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	c := &cell{
		reactor: r,
		compute: func() int { return compute(dep.Value()) },
	}
	dep.(*cell).dependents = append(dep.(*cell).dependents, c)
	r.cells = append(r.cells, c)
	c.value = c.compute()
	return c
}

// CreateCompute2 creates a compute cell depending on two cells.
func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	c := &cell{
		reactor: r,
		compute: func() int { return compute(dep1.Value(), dep2.Value()) },
	}
	dep1.(*cell).dependents = append(dep1.(*cell).dependents, c)
	dep2.(*cell).dependents = append(dep2.(*cell).dependents, c)
	r.cells = append(r.cells, c)
	c.value = c.compute()
	return c
}

// Value returns the current value of the cell.
func (c *cell) Value() int {
	return c.value
}

// SetValue sets the value of an input cell and propagates the change to all
// cells that (transitively) depend on it, reaching a new stable state.
func (c *cell) SetValue(value int) {
	if c.value == value {
		return
	}
	c.value = value

	// Collect all cells that transitively depend on this cell.
	affected := make(map[*cell]bool)
	stack := []*cell{c}
	for len(stack) > 0 {
		current := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, dependent := range current.dependents {
			if !affected[dependent] {
				affected[dependent] = true
				stack = append(stack, dependent)
			}
		}
	}

	// Recompute affected cells in creation order, which is a topological
	// order, so every dependency is up to date before its dependents.
	for _, cell := range c.reactor.cells {
		if cell.compute == nil || !affected[cell] {
			continue
		}
		if newValue := cell.compute(); newValue != cell.value {
			cell.value = newValue
			for _, cb := range cell.callbacks {
				cb.fn(newValue)
			}
		}
	}
}

// AddCallback registers a callback called whenever the cell's value changes
// to a new stable state, and returns a Canceler to remove it.
func (c *cell) AddCallback(fn func(int)) Canceler {
	id := c.nextCallbackID
	c.nextCallbackID++
	c.callbacks = append(c.callbacks, callback{id: id, fn: fn})
	return &canceler{cell: c, id: id}
}

// Cancel removes the callback from its cell. Calling Cancel more than once
// has no effect.
func (cn *canceler) Cancel() {
	for i, cb := range cn.cell.callbacks {
		if cb.id == cn.id {
			n := len(cn.cell.callbacks)
			copy(cn.cell.callbacks[i:], cn.cell.callbacks[i+1:])
			cn.cell.callbacks[n-1] = callback{}
			cn.cell.callbacks = cn.cell.callbacks[:n-1]
			return
		}
	}
}
